    if(ui.service==='藏经阁'&&borrowed.length)body+='<section class="sa-borrowed"><h4>在借典籍</h4>'+borrowed.map(([id,b])=>'<div class="sa-borrow-row"><span>'+E(b.名称)+' · 应还 '+E(b.应还时间)+'</span>'+button('申请归还','return',{id})+'</div>').join('')+'</section>';
